import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

// Zenith: a small, self-contained voxel survival climb.
const canvas=document.querySelector('#game-canvas');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x26171e);
scene.fog=new THREE.FogExp2(0x30202a,.012);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,220);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
scene.add(new THREE.HemisphereLight(0xffc5a1,0x23152c,1.5));
const keyLight=new THREE.DirectionalLight(0xffa26e,2.4);keyLight.position.set(-14,28,14);keyLight.castShadow=true;keyLight.shadow.mapSize.set(1024,1024);keyLight.shadow.camera.left=-38;keyLight.shadow.camera.right=38;keyLight.shadow.camera.top=30;keyLight.shadow.camera.bottom=-24;keyLight.shadow.bias=-.0005;scene.add(keyLight);
const ambientGlow=new THREE.PointLight(0xff4b27,22,28,2);ambientGlow.position.set(-35,0,0);scene.add(ambientGlow);
const playerLight=new THREE.PointLight(0xffa45f,5.5,12,2);scene.add(playerLight);
const worldGroup=new THREE.Group();scene.add(worldGroup);const decoGroup=new THREE.Group();scene.add(decoGroup);const fxGroup=new THREE.Group();scene.add(fxGroup);
const raycaster=new THREE.Raycaster();raycaster.far=8;const pointer=new THREE.Vector2(0,0);
const matColors={ash:0x49343a,stone:0x51474c,obsidian:0x292333,crimson:0x733e50,corrupt:0x51447a,honey:0xb78036,grass:0x586348,ore:0xa44f50,hellstone:0x9b4431,wood:0x684a39,platform:0x957064};
function noiseTexture(base,seed=1){let c=document.createElement('canvas');c.width=c.height=128;let x=c.getContext('2d');x.fillStyle='#'+base.toString(16).padStart(6,'0');x.fillRect(0,0,128,128);let s=seed;const rand=()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296};for(let i=0;i<1200;i++){let a=rand()>.5?255:0;x.fillStyle=`rgba(${a},${a},${a},${rand()*.12})`;let z=1+rand()*5;x.fillRect(rand()*128,rand()*128,z,z)}let t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(1,1);return t}
const mats={};for(const [k,col] of Object.entries(matColors)){let texture=noiseTexture(col,Array.from(k).reduce((a,c)=>a+c.charCodeAt(0),11));mats[k]=new THREE.MeshStandardMaterial({color:0xffffff,map:texture,roughness:k==='obsidian'?.3:.88,metalness:k==='obsidian'?.18:0,emissive:k==='hellstone'?0x7d2314:k==='ore'?0x35131b:0x000000,emissiveIntensity:.42})}
const blockGeo=new THREE.BoxGeometry(1,1,1);const blockRecords=[];const blockMeshes={};const blockById={};
const cell=(x,y,z)=>`${x},${y},${z}`;const blocks=new Map();let worldSeed=5162024;
function seeded(x,y,z){let n=Math.sin(x*127.1+y*311.7+z*74.7+worldSeed)*43758.5453;return n-Math.floor(n)}
function floorAt(x,z=0){const rise=Math.max(0,x+34)*.83;return Math.floor(2+rise+Math.sin(x*.31)*1.1+Math.sin(z*.7+x*.18)*.7)}
function zoneAt(y){return y<15?'UNDERWORLD':y<29?'ASHEN CAVERNS':y<43?'HONEY WILDS':y<57?'FUSED EVIL':'CELEBRATION BEACH'}
function blockType(x,y,z,top){let h=floorAt(x,z);if(y>=h-1&&y<=h)return y===h&&h>44?'grass':h<12?'hellstone':h>42?(x%2===0?'crimson':'corrupt'):'ash';let r=seeded(x,y,z);if(r<.012&&y>9)return 'ore';if(y<5)return r<.42?'hellstone':'obsidian';if(y>40)return r<.32?'crimson':'corrupt';if(y>27&&r<.28)return 'honey';return r<.16?'obsidian':r<.25?'stone':'ash'}
function generateWorld(){for(let x=-46;x<=64;x++){for(let z=-4;z<=4;z++){let h=floorAt(x,z);for(let y=-10;y<=h;y++){let type=blockType(x,y,z,y===h);if(y===h+1)continue;let b={x,y,z,type};blocks.set(cell(x,y,z),b)}}}rebuildInstances();makeEnvironment()}
function rebuildInstances(){for(const mesh of Object.values(blockMeshes)){worldGroup.remove(mesh);mesh.dispose?.()}for(const k of Object.keys(blockMeshes))delete blockMeshes[k];for(const k of Object.keys(blockById))delete blockById[k];const groups={};for(const b of blocks.values())(groups[b.type]??=[]).push(b);for(const [type,list] of Object.entries(groups)){let m=new THREE.InstancedMesh(blockGeo,mats[type],list.length);m.castShadow=true;m.receiveShadow=true;m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);let obj=new THREE.Object3D();list.forEach((b,i)=>{obj.position.set(b.x,b.y,b.z);obj.updateMatrix();m.setMatrixAt(i,obj.matrix);blockById[type+':'+i]=b});m.userData={type,list};worldGroup.add(m);blockMeshes[type]=m}}
function setBlock(x,y,z,type){let k=cell(x,y,z);if(blocks.has(k))return false;let b={x,y,z,type};blocks.set(k,b);rebuildInstances();return true}
function removeBlock(b){if(!b)return;blocks.delete(cell(b.x,b.y,b.z));rebuildInstances()}
const player={x:-31,y:floorAt(-31)+1.03,z:0,vx:0,vy:0,vz:0,hp:100,maxHp:100,mana:60,maxMana:60,onGround:false,face:1,invuln:0,attackCd:0,mineCd:0,dodge:0,checkpoint:{x:-31,y:floorAt(-31)+1.03,z:0},inventory:{ash:0,hellstone:0,ore:0,wood:6,life:0,torch:4},weapon:0,alive:true};
const weaponList=[{name:'CINDERBLADE',art:'⚔',type:'MELEE',dmg:18},{name:'EMBER BOW',art:'➶',type:'RANGED',dmg:12},{name:'SOUL FLARE',art:'✦',type:'MAGIC',dmg:22}];
let keys={},paused=false,inventoryOpen=false,worldTime=0,lastTime=performance.now(),boss=null,enemies=[],projectiles=[],particles=[],toastTimer=0,checkpointLabel='ASHEN RIFT',oreCount=0,placeMode=false,spawnTick=0;
const playerGroup=new THREE.Group();scene.add(playerGroup);
const bodyMat=new THREE.MeshStandardMaterial({color:0xd9b7a3,roughness:.72}),coatMat=new THREE.MeshStandardMaterial({color:0x392b45,roughness:.83}),goldMat=new THREE.MeshStandardMaterial({color:0xf7a462,emissive:0x7b2c18,emissiveIntensity:.45,roughness:.45});
const body=new THREE.Mesh(new THREE.CapsuleGeometry(.34,.62,4,8),coatMat);body.position.y=.78;body.castShadow=true;playerGroup.add(body);
const head=new THREE.Mesh(new THREE.SphereGeometry(.27,12,9),bodyMat);head.position.set(0,1.42,0);head.castShadow=true;playerGroup.add(head);
const hood=new THREE.Mesh(new THREE.ConeGeometry(.34,.48,5),new THREE.MeshStandardMaterial({color:0x4a3041,roughness:.9}));hood.position.set(0,1.73,0);hood.rotation.z=Math.PI;playerGroup.add(hood);
const blade=new THREE.Mesh(new THREE.BoxGeometry(.09,.76,.1),new THREE.MeshStandardMaterial({color:0xffbd8b,metalness:.7,roughness:.25,emissive:0xff571e,emissiveIntensity:.65}));blade.position.set(.49,.85,0);blade.rotation.z=-.55;playerGroup.add(blade);
function makeEnvironment(){
 // broken basalt teeth and a molten underworld lake
 for(let i=0;i<55;i++){let x=-49+Math.random()*124,y=floorAt(x,0)+.5,z=(Math.random()-.5)*8;let h=.4+Math.random()*2.2;let rock=new THREE.Mesh(new THREE.ConeGeometry(.18+Math.random()*.38,h,5),new THREE.MeshStandardMaterial({color:i%4===0?0x8c5142:0x51444b,roughness:.9}));rock.position.set(x,y+h/2,z);rock.rotation.z=(Math.random()-.5)*.8;rock.castShadow=true;decoGroup.add(rock)}
 const lava=new THREE.Mesh(new THREE.PlaneGeometry(34,15),new THREE.MeshStandardMaterial({color:0x9e301d,emissive:0xff3f18,emissiveIntensity:1.55,roughness:.26,metalness:.08,transparent:true,opacity:.88}));lava.rotation.x=-Math.PI/2;lava.position.set(-38,-1.7,0);decoGroup.add(lava);
 const moon=new THREE.Mesh(new THREE.SphereGeometry(3,24,16),new THREE.MeshBasicMaterial({color:0xffb073}));moon.position.set(4,70,-48);scene.add(moon);
 for(let i=0;i<30;i++){const c=new THREE.Mesh(new THREE.IcosahedronGeometry(.15+Math.random()*.4,1),new THREE.MeshStandardMaterial({color:i%2?0x655080:0x733f51,roughness:.9}));let x=10+Math.random()*47,h=floorAt(x,0);c.position.set(x,h+1.5+Math.random()*3,(Math.random()-.5)*5);c.scale.y=.5+Math.random();decoGroup.add(c)}
}
function toast(title,copy,kind=''){let stack=document.querySelector('#toast-stack'),el=document.createElement('div');el.className='float-toast '+kind;el.textContent=title+'  ·  '+copy;stack.append(el);setTimeout(()=>el.remove(),2600)}
function quest(title,copy){document.querySelector('#toast-title').textContent=title;document.querySelector('#toast-copy').textContent=copy;let el=document.querySelector('#toast');el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function updateBiome(){let zone=zoneAt(player.y);document.querySelector('#biome-label').textContent=zone;let colors={UNDERWORLD:[0x30202a,0x30202a,0xff884e], 'ASHEN CAVERNS':[0x171c2a,0x22253a,0x8389c4],'HONEY WILDS':[0x273128,0x343625,0xf2bc59],'FUSED EVIL':[0x291721,0x401c34,0xe66c89],'CELEBRATION BEACH':[0x172b3b,0x476c77,0x79d9cc]};let c=colors[zone];scene.fog.color.setHex(c[0]);scene.background.setHex(c[1]);keyLight.color.setHex(c[2]);let depth=zone==='UNDERWORLD'?'HELL · 1,240m':zone==='ASHEN CAVERNS'?'CAVERNS · 890m':zone==='HONEY WILDS'?'HIVE · 540m':zone==='FUSED EVIL'?'THE EVIL · 210m':'SURFACE · 0m';document.querySelector('#depth-readout').textContent=depth;document.querySelector('#objective-title').textContent=player.y<14?'Climb out of the Ashen Deep':player.y<29?'Break through the cavern roof':player.y<43?'Cross the Honey Wilds':player.y<57?'Outrun the fused evil':'Reach the open surface';document.querySelector('#objective-copy').textContent=player.y<14?'Mine upward. Find a way through the burning crust.':player.y<29?'The ash is thinning. Keep climbing toward the light.':player.y<43?'The hive is alive. Keep your guard up.':player.y<57?'Crimson and corruption share this cursed ground.':'You made it. The world is yours to shape.';document.querySelector('#progress-fill').style.width=Math.min(100,Math.max(3,player.y/65*100))+'%';document.querySelector('#height-readout').textContent=Math.max(0,Math.floor(player.y))+'m';document.querySelector('#coords').textContent=`X ${Math.floor(player.x)} · Y ${Math.floor(player.y).toString().padStart(2,'0')}`}
function updateHUD(){document.querySelector('#hp-text').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;let hearts=document.querySelector('#hearts');hearts.innerHTML='';for(let i=0;i<Math.ceil(player.maxHp/10);i++){let e=document.createElement('span');e.className='heart'+(i*10>=player.hp?' empty':'');e.textContent='♥';hearts.append(e)}document.querySelector('#mana-fill').style.width=(player.mana/player.maxMana*100)+'%';document.querySelector('#mana-text').textContent=Math.ceil(player.mana);document.querySelector('#weapon-name').textContent=weaponList[player.weapon].name;document.querySelector('#weapon-art').textContent=weaponList[player.weapon].art;document.querySelector('#weapon-sub').textContent=`${weaponList[player.weapon].type} · ${weaponList[player.weapon].dmg} DMG`;document.querySelector('#pause-depth').textContent=document.querySelector('#depth-readout').textContent;document.querySelector('#pause-ore').textContent=oreCount;renderHotbar()}
function renderHotbar(){let bar=document.querySelector('#hotbar');bar.innerHTML='';let slots=[['⚔','Blade',1],['▧','Ash',player.inventory.ash],['◆','Hellstone',player.inventory.hellstone],['✥','Demonite',player.inventory.ore],['♨','Torch',player.inventory.torch],['♥','Life crystal',player.inventory.life],['▰','Wood',player.inventory.wood]];slots.forEach((s,i)=>{let d=document.createElement('button');d.className='slot'+(i===player.weapon?' selected':'');d.innerHTML=`<span class="slot-key">${i<3?i+1:'·'}</span><span class="slot-icon">${s[0]}</span><span class="slot-count">${s[2]||''}</span>`;d.title=s[1];d.onclick=()=>{if(i<3){player.weapon=i;updateHUD()}else{document.querySelector('#inventory-overlay').classList.remove('hidden');inventoryOpen=true;renderInventory()}};bar.append(d)})}

