function renderHotbar(){let bar=document.querySelector('#hotbar');bar.innerHTML='';let slots=[['⚔','Cinderblade',1],['➶','Ember bow',1],['✦','Soul flare',1],['▧','Ash',player.inventory.ash],['◆','Hellstone',player.inventory.hellstone],['✥','Demonite',player.inventory.ore],['♨','Torch',player.inventory.torch]];slots.forEach((s,i)=>{let d=document.createElement('button');d.className='slot'+(i===player.weapon?' selected':'');d.innerHTML=`<span class="slot-key">${i<3?i+1:'·'}</span><span class="slot-icon">${s[0]}</span><span class="slot-count">${s[2]||''}</span>`;d.title=s[1];d.onclick=()=>{if(i<3){player.weapon=i;updateHUD()}else{document.querySelector('#inventory-overlay').classList.remove('hidden');inventoryOpen=true;renderInventory()}};bar.append(d)})}

function initCombatArt(){
 const shadow=new THREE.Mesh(new THREE.CircleGeometry(.65,20),new THREE.MeshBasicMaterial({color:0x100b15,transparent:true,opacity:.35}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.03;playerGroup.add(shadow);
 const glow=new THREE.Mesh(new THREE.SphereGeometry(.055,8,6),new THREE.MeshBasicMaterial({color:0xffae63}));glow.position.set(0,1.35,.27);playerGroup.add(glow);
}
function nearestBlock(){raycaster.setFromCamera(pointer,camera);let hits=raycaster.intersectObjects(Object.values(blockMeshes),false);return hits.length?hits[0]:null}
function mine(){if(player.mineCd>0)return;let hit=nearestBlock();if(!hit)return;let b=hit.object.userData.list[hit.instanceId];if(!b)return;let dx=b.x-player.x,dy=b.y-(player.y+.9),dz=b.z-player.z;if(Math.hypot(dx,dy,dz)>6)return;player.mineCd=.26;removeBlock(b);if(b.type==='ore'){player.inventory.ore++;oreCount++;toast('Demonite recovered','Rare ore · +1','good')}else if(b.type==='hellstone'){player.inventory.hellstone++;toast('Hellstone mined','Forged in the deep','good')}else if(b.type==='wood')player.inventory.wood++;else player.inventory.ash++;spawnBurst(b.x,b.y,b.z,b.type==='ore'?0xc77479:0xc2a294,5);updateHUD()}
function build(){if(player.inventory.ash<1&&player.inventory.hellstone<1){toast('No building material','Mine ash or hellstone first','bad');return}let hit=nearestBlock();let p;if(hit){let n=hit.face.normal.clone().transformDirection(hit.object.matrixWorld);p=hit.point.clone().addScaledVector(n,.51);p.set(Math.round(p.x),Math.round(p.y),Math.round(p.z))}else p=new THREE.Vector3(Math.round(player.x+player.face),Math.floor(player.y-.2),Math.round(player.z));let px=Math.floor(player.x),py=Math.floor(player.y),pz=Math.round(player.z);if(Math.abs(p.x-px)<1&&Math.abs(p.y-py)<2&&Math.abs(p.z-pz)<1){toast('Too close','You need room to place that','bad');return}let material=player.inventory.hellstone>0?'hellstone':'ash';if(setBlock(p.x,p.y,p.z,material)){player.inventory[material]--;toast('Block placed','Your path, your rules','good');updateHUD()}}
function attack(){if(!player.alive||player.attackCd>0)return;let w=weaponList[player.weapon];player.attackCd=player.weapon===2?.48:.35;if(player.weapon===0){blade.rotation.z=-1.85;setTimeout(()=>blade.rotation.z=-.55,120);for(const target of [...enemies,...(boss?[boss]:[])]){if(Math.hypot(target.mesh.position.x-player.x,target.mesh.position.y-(player.y+1),target.mesh.position.z-player.z)<2.35){damageTarget(target,w.dmg)}}}else{if(player.weapon===2&&player.mana<5){toast('Out of mana','Wait for your magic to recover','bad');return}if(player.weapon===2)player.mana-=5;let start=new THREE.Vector3(player.x+player.face*.5,player.y+1,player.z),target=aimPoint();let dir=target.sub(start).normalize();let speed=player.weapon===1?17:13;let bolt=new THREE.Mesh(new THREE.SphereGeometry(player.weapon===1?.1:.16,10,8),new THREE.MeshBasicMaterial({color:player.weapon===1?0xffd69a:0xbba2ff}));bolt.position.copy(start);scene.add(bolt);projectiles.push({mesh:bolt,v:dir.multiplyScalar(speed),life:2,damage:w.dmg,owner:'player',glow:player.weapon===1?0xffaa70:0x9f87ff});if(player.weapon===2)bolt.scale.setScalar(1.35);updateHUD()}}
function aimPoint(){raycaster.setFromCamera(pointer,camera);let hit=raycaster.intersectObjects(Object.values(blockMeshes),false)[0];if(hit)return hit.point.clone();let v=new THREE.Vector3(pointer.x,pointer.y,.5).unproject(camera);let dir=v.sub(camera.position).normalize();return camera.position.clone().addScaledVector(dir,24)}
function damageTarget(t,dmg){if(!t||t.dead)return;t.hp-=dmg;if(t===boss){document.querySelector('#boss-fill').style.width=Math.max(0,t.hp/t.maxHp*100)+'%';if(t.hp<t.maxHp*.5)document.querySelector('#boss-phase').textContent='PHASE II · ENRAGED'}if(t.hp<=0){t.dead=true;scene.remove(t.mesh);if(t===boss){document.querySelector('#boss-bar').classList.add('hidden');boss=null;player.inventory.ore+=7;oreCount+=7;player.inventory.life++;player.maxHp+=10;player.hp=Math.min(player.maxHp,player.hp+30);toast('The Eye has fallen','Life crystal and 7 Demonite','good');quest('A crack in the dark','The surface is closer now.');updateHUD()}else{let idx=enemies.indexOf(t);if(idx>=0)enemies.splice(idx,1);player.inventory.ash+=1;if(Math.random()<.25)player.inventory.hellstone++;toast('Demonite slain','Recovered a little ash','good');updateHUD()}}}
